function formatMessageDateDivider(dateStrOrObj: string | Date | null | undefined): string {
  if (!dateStrOrObj) return '';
  try {
    const d = typeof dateStrOrObj === 'string' ? new Date(dateStrOrObj) : dateStrOrObj;
    if (isNaN(d.getTime())) return '';
    
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const msgDate = new Date(d.getFullYear(), d.getMonth(), d.getDate());
    
    const diffMs = today.getTime() - msgDate.getTime();
    const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));
    
    const dateStr = d.toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' });
    
    if (diffDays === 0) {
      return 'TODAY';
    } else if (diffDays === 1) {
      return 'YESTERDAY';
    } else if (diffDays > 1 && diffDays < 7) {
      return d.toLocaleDateString('en-US', { weekday: 'long' }).toUpperCase();
    } else {
      return d.toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' }).toUpperCase();
    }
  } catch {
    return '';
  }
}

function expandKnownTemplate(name: string, params?: any[] | null): string | null {
  const raw = KNOWN_TEMPLATE_BODIES[name.toLowerCase()] || KNOWN_TEMPLATE_BODIES[name];
  if (!raw) return null;
  if (!params || !params.length) {
    return raw.replace(/\{\{\d+\}\}/g, '...');
  }
  let result = raw;
  params.forEach((val, idx) => {
    result = result.replace(new RegExp(`\\{\\{${idx + 1}\\}\\}`, 'g'), String(val ?? ''));
  });
  result = result.replace(/\{\{\d+\}\}/g, '...');
  return result;
}

function formatFlowResponse(rawText: string | null | undefined): string | null {
  if (!rawText) return null;
  const match = rawText.match(/\[Flow Response:\s*({[\s\S]*?})\]/i);
  if (!match || !match[1]) return null;
  try {
    const data = JSON.parse(match[1]);
    const lines: string[] = ['📋 WhatsApp Form Submitted:'];
    for (const [k, v] of Object.entries(data)) {
      if (k === 'flow_token' || k.startsWith('__')) continue;
      if (v === undefined || v === null || v === '') continue;
      let cleanKey = k.replace(/^screen_\d+_?/i, '').replace(/_\d+$/, '').replace(/_/g, ' ').trim();
      cleanKey = cleanKey.split(' ').map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
      lines.push(`• ${cleanKey}: ${String(v).trim()}`);
    }
    return lines.length > 1 ? lines.join('\n') : '📋 WhatsApp Form Submitted';
  } catch {
    return '📋 WhatsApp Form Submitted';
  }
}

function formatMessageSnippet(text: string | null | undefined): string {
  if (!text) return '';
  if (text.includes('[Flow Response:')) {
    try {
      const match = text.match(/\[Flow Response:\s*({[\s\S]*?})\]/i);
      if (match && match[1]) {
        const data = JSON.parse(match[1]);
        const nameKey = Object.keys(data).find((k) => k.toLowerCase().includes('name'));
        const nameVal = nameKey ? String(data[nameKey]).trim() : '';
        if (nameVal) return `📋 Form: ${nameVal}`;
      }
    } catch {}
    return '📋 WhatsApp Form Submitted';
  }
  return text;
}

function getDisplayMessageBody(msg: {
  body?: string | null;
  content_type?: string | null;
  template_name?: string | null;
  template_params?: any[] | null;
}): string {
  const b = msg.body;
  const tName = msg.template_name;
  if (tName && (!b || b.startsWith('[Template:') || b.startsWith('Template:'))) {
    const expanded = expandKnownTemplate(tName, msg.template_params);
    if (expanded) return expanded;
    return `Template: ${tName.replace(/_/g, ' ')}`;
  }
  if (b && b.includes('[Flow Response:')) {
    const formattedFlow = formatFlowResponse(b);
    if (formattedFlow) return formattedFlow;
  }
  if (b && b.trim()) {
    return b;
  }
  const ct = msg.content_type;
  if (ct === 'image') return '[Photo]';
  if (ct === 'video') return '[Video]';
  if (ct === 'document') return '[Document]';
  if (ct === 'audio') return '[Audio]';
  if (ct === 'sticker') return '[Sticker]';
  if (ct === 'location') return '[Location]';
  if (tName) return `Template: ${tName.replace(/_/g, ' ')}`;
  return '[Message]';
}

function renderMessageWithLinks(text: string, isInbound: boolean) {
  if (!text) return null;
  const urlRegex = /(https?:\/\/[^\s]+|www\.[^\s]+)/g;
  const parts = text.split(urlRegex);

  return parts.map((part, index) => {
    if (part.match(urlRegex)) {
      const href = part.startsWith('http') ? part : `https://${part}`;
      return (
        <a
          key={index}
          href={href}
          target="_blank"
          rel="noopener noreferrer"
          onClick={(e) => e.stopPropagation()}
          className={`underline font-medium break-all hover:opacity-80 transition-opacity ${
            isInbound ? 'text-blue-600 dark:text-blue-400' : 'text-teal-100 underline decoration-teal-200'
          }`}
        >
          {part}
        </a>
      );
    }
    return part;
  });
}

function formatWhatsAppHeaderDate(dateStrOrObj: string | Date | null | undefined): string {
  if (!dateStrOrObj) return '';
  try {
    const d = typeof dateStrOrObj === 'string' ? new Date(dateStrOrObj) : dateStrOrObj;
    if (isNaN(d.getTime())) return '';
    
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const msgDate = new Date(d.getFullYear(), d.getMonth(), d.getDate());
    
    const diffMs = today.getTime() - msgDate.getTime();
    const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));
    
    const timeStr = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
    const dateStr = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    
    if (diffDays === 0) {
      return `Today at ${timeStr} (${dateStr})`;
    } else if (diffDays === 1) {
      return `Yesterday at ${timeStr} (${dateStr})`;
    } else if (diffDays > 1 && diffDays < 7) {
      const weekday = d.toLocaleDateString('en-US', { weekday: 'long' });
      return `${weekday} at ${timeStr} (${dateStr})`;
    } else {
      return `${dateStr} at ${timeStr}`;
    }
  } catch {
    return '';
  }
}

function normalizeNoteColor(raw?: string | null): 'slate' | 'blue' | 'amber' | 'rose' | 'emerald' | 'violet' {
  const c = (raw || '').trim().toLowerCase();
  if (c === 'red' || c === 'rose') return 'rose';
  if (c === 'yellow' || c === 'amber') return 'amber';
  if (c === 'green' || c === 'emerald') return 'emerald';
  if (c === 'purple' || c === 'violet') return 'violet';
  if (c === 'blue') return 'blue';
  return 'slate';
}

