function getAvatarColor(nameOrPhone: string = ''): string {
  const colors = [
    'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-950/60 dark:text-blue-300 dark:border-blue-800',
    'bg-indigo-100 text-indigo-800 border-indigo-200 dark:bg-indigo-950/60 dark:text-indigo-300 dark:border-indigo-800',
    'bg-violet-100 text-violet-800 border-violet-200 dark:bg-violet-950/60 dark:text-violet-300 dark:border-violet-800',
    'bg-emerald-100 text-emerald-800 border-emerald-200 dark:bg-emerald-950/60 dark:text-emerald-300 dark:border-emerald-800',
    'bg-amber-100 text-amber-900 border-amber-200 dark:bg-amber-950/60 dark:text-amber-300 dark:border-amber-800',
    'bg-rose-100 text-rose-800 border-rose-200 dark:bg-rose-950/60 dark:text-rose-300 dark:border-rose-800',
    'bg-teal-100 text-teal-800 border-teal-200 dark:bg-teal-950/60 dark:text-teal-300 dark:border-teal-800',
  ];
  let hash = 0;
  for (let i = 0; i < nameOrPhone.length; i++) {
    hash = nameOrPhone.charCodeAt(i) + ((hash << 5) - hash);
  }
  return colors[Math.abs(hash) % colors.length];
}

const TIME_OPTIONS: string[] = (() => {
  const options: string[] = [];
  for (let h = 8; h <= 21; h++) {
    const period = h >= 12 ? 'PM' : 'AM';
    const displayH = h > 12 ? h - 12 : (h === 0 ? 12 : h);
    const hourStr = String(displayH).padStart(2, '0');
    options.push(`${hourStr}:00 ${period}`);
    if (h < 21) {
      options.push(`${hourStr}:15 ${period}`);
      options.push(`${hourStr}:30 ${period}`);
      options.push(`${hourStr}:45 ${period}`);
    }
  }
  return options;
})();

function getMonthDays(year: number, monthIndex: number) {
  const firstDay = new Date(year, monthIndex, 1).getDay();
  const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
  const prevMonthDays = new Date(year, monthIndex, 0).getDate();
  const days: { day: number; isCurrentMonth: boolean; dateStr: string }[] = [];
  for (let i = firstDay - 1; i >= 0; i--) {
    const d = prevMonthDays - i;
    const prevMonth = monthIndex === 0 ? 11 : monthIndex - 1;
    const prevYear = monthIndex === 0 ? year - 1 : year;
    days.push({
      day: d,
      isCurrentMonth: false,
      dateStr: `${prevYear}-${String(prevMonth + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`
    });
  }
  for (let d = 1; d <= daysInMonth; d++) {
    days.push({
      day: d,
      isCurrentMonth: true,
      dateStr: `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`
    });
  }
  const remaining = (7 - (days.length % 7)) % 7;
  for (let d = 1; d <= remaining; d++) {
    const nextMonth = monthIndex === 11 ? 0 : monthIndex + 1;
    const nextYear = monthIndex === 11 ? year + 1 : year;
    days.push({
      day: d,
      isCurrentMonth: false,
      dateStr: `${nextYear}-${String(nextMonth + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`
    });
  }
  return days;
}

function getFollowupDateString(offsetDays: number = 0): string {
  const d = new Date();
  d.setDate(d.getDate() + offsetDays);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function parseFollowupTime(timeStr?: string | null) {
  const def = { hour: '10', minute: ':00', period: 'AM' as const };
  if (!timeStr) return def;
  const match = timeStr.trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i);
  if (!match) return def;
  let h = parseInt(match[1], 10);
  const m = match[2];
  const p = (match[3] || 'AM').toUpperCase() === 'PM' ? 'PM' : 'AM';
  const hStr = String(h).padStart(2, '0');
  const mStr = `:${m}`;
  return { hour: hStr, minute: mStr, period: p as 'AM' | 'PM' };
}

function getFollowupScheduleInfo(dateStr?: string | null, timeStr?: string | null) {
  if (!dateStr) return null;
  try {
    const parts = dateStr.split('-');
    if (parts.length !== 3) return { status: 'future' as const, label: dateStr, shortLabel: dateStr, time: timeStr || '10:00 AM', diffDays: 0 };
    const y = parseInt(parts[0], 10);
    const m = parseInt(parts[1], 10);
    const d = parseInt(parts[2], 10);
    if (isNaN(y) || isNaN(m) || isNaN(d)) return { status: 'future' as const, label: dateStr, shortLabel: dateStr, time: timeStr || '10:00 AM', diffDays: 0 };

    const target = new Date(y, m - 1, d);
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const targetDate = new Date(target.getFullYear(), target.getMonth(), target.getDate());

    const diffDays = Math.round((targetDate.getTime() - today.getTime()) / 86400000);
    const time = timeStr || '10:00 AM';

    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const formattedShort = `${monthNames[m - 1]} ${d}`;

    if (diffDays < 0) {
      return {
        status: 'overdue' as const,
        label: diffDays === -1 ? 'Overdue (Yesterday)' : `Overdue (${formattedShort})`,
        shortLabel: formattedShort,
        time,
        diffDays
      };
    }
    if (diffDays === 0) {
      return {
        status: 'today' as const,
        label: 'Today',
        shortLabel: 'Today',
        time,
        diffDays
      };
    }
    if (diffDays === 1) {
      return {
        status: 'tomorrow' as const,
        label: 'Tomorrow',
        shortLabel: 'Tomorrow',
        time,
        diffDays
      };
    }
    return {
      status: 'future' as const,
      label: formattedShort,
      shortLabel: formattedShort,
      time,
      diffDays
    };
  } catch {
    return { status: 'future' as const, label: dateStr, shortLabel: dateStr, time: timeStr || '10:00 AM', diffDays: 0 };
  }
}

function formatMilitaryTo12(timeStr: string | null | undefined): string {
  if (!timeStr) return '';
  const m = timeStr.trim().match(/^(\d{1,2}):(\d{2})$/);
  if (!m) return timeStr;
  let h = parseInt(m[1], 10);
  const min = m[2];
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h % 12 === 0 ? 12 : h % 12;
  return `${h}:${min} ${ampm}`;
}

function formatRoleName(role?: string): string {
  if (!role) return 'Staff';
  const r = role.toLowerCase().trim();
  if (r === 'super_admin' || r === 'superadmin') return 'Super Admin';
  if (r === 'admin') return 'Admin';
  if (r === 'sales') return 'Sales Executive';
  if (r === 'marketing') return 'Marketing Specialist';
  if (r === 'doctor') return 'Doctor / Consultant';
  if (r === 'receptionist') return 'Receptionist';
  if (r === 'agent') return 'Support Agent';
  if (r === 'viewer') return 'Viewer';
  return role.charAt(0).toUpperCase() + role.slice(1).replace(/_/g, ' ');
}

