function FollowupCalendarPopover({
  currentDate,
  calViewDate,
  setCalViewDate,
  onSelectDate,
  onClear,
  onClose,
}: {
  currentDate?: string | null;
  calViewDate: Date;
  setCalViewDate: React.Dispatch<React.SetStateAction<Date>>;
  onSelectDate: (dateStr: string) => void;
  onClear: () => void;
  onClose: () => void;
}) {
  return (
    <>
      <div
        className="fixed inset-0 z-30"
        onClick={(e) => {
          e.stopPropagation();
          onClose();
        }}
      />
      <div
        className="absolute right-0 top-full mt-1 z-40 w-64 bg-surface border border-border rounded-lg shadow-xl p-3 animate-in fade-in zoom-in-95 duration-150"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Month/Year Nav */}
        <div className="flex items-center justify-between pb-2 mb-2 border-b border-border">
          <button
            type="button"
            onClick={() => {
              setCalViewDate((prev) => new Date(prev.getFullYear(), prev.getMonth() - 1, 1));
            }}
            className="p-1 rounded hover:bg-surface-subtle text-text-secondary hover:text-text-primary transition-colors cursor-pointer"
            title="Previous month"
          >
            <ChevronLeft className="w-3.5 h-3.5" />
          </button>
          <span className="text-xs font-semibold text-text-primary select-none">
            {calViewDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
          </span>
          <button
            type="button"
            onClick={() => {
              setCalViewDate((prev) => new Date(prev.getFullYear(), prev.getMonth() + 1, 1));
            }}
            className="p-1 rounded hover:bg-surface-subtle text-text-secondary hover:text-text-primary transition-colors cursor-pointer"
            title="Next month"
          >
            <ChevronRight className="w-3.5 h-3.5" />
          </button>
        </div>

        {/* Weekday headers */}
        <div className="grid grid-cols-7 gap-1 text-center mb-1">
          {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map((d) => (
            <span key={d} className="text-[10px] font-semibold text-text-muted select-none">
              {d}
            </span>
          ))}
        </div>

        {/* Day Grid */}
        <div className="grid grid-cols-7 gap-1 text-center">
          {getMonthDays(calViewDate.getFullYear(), calViewDate.getMonth()).map((cell, idx) => {
            const isSelected = currentDate === cell.dateStr;
            const isToday = cell.dateStr === getFollowupDateString(0);
            return (
              <button
                key={idx}
                type="button"
                onClick={() => {
                  onSelectDate(cell.dateStr);
                  onClose();
                }}
                className={`h-6 w-full rounded text-[11px] font-medium flex items-center justify-center transition-colors cursor-pointer ${
                  isSelected
                    ? 'bg-accent text-white font-bold shadow-xs'
                    : isToday
                    ? 'bg-accent/15 text-accent font-semibold hover:bg-accent/25'
                    : cell.isCurrentMonth
                    ? 'text-text-primary hover:bg-surface-subtle'
                    : 'text-text-muted/40 hover:bg-surface-subtle hover:text-text-muted'
                }`}
                title={cell.dateStr}
              >
                {cell.day}
              </button>
            );
          })}
        </div>

        {/* Popover Footer */}
        <div className="pt-2 mt-2 border-t border-border flex items-center justify-between">
          <button
            type="button"
            onClick={() => {
              onClear();
              onClose();
            }}
            className="text-[10px] text-rose-600 hover:text-rose-700 hover:bg-rose-50 px-2 py-0.5 rounded border border-rose-200 font-medium transition-colors cursor-pointer"
          >
            Clear
          </button>
          <button
            type="button"
            onClick={onClose}
            className="text-[10px] text-text-muted hover:text-text-primary px-2 py-0.5 rounded hover:bg-surface-subtle transition-colors cursor-pointer"
          >
            Close
          </button>
        </div>
      </div>
    </>
  );
}

function FollowupTimePickerPopover({
  initialTime,
  onSave,
  onClose,
}: {
  initialTime?: string | null;
  onSave: (newTime: string) => void;
  onClose: () => void;
}) {
  const parsed = parseFollowupTime(initialTime || '10:00 AM');
  const [hour, setHour] = useState(parsed.hour || '10');
  const [minute, setMinute] = useState(parsed.minute.replace(':', '') || '00');
  const [period, setPeriod] = useState<'AM' | 'PM'>(parsed.period || 'AM');

  const formatCleanTime = (hVal: string, mVal: string, pVal: 'AM' | 'PM') => {
    const hNum = parseInt(hVal, 10);
    const safeH = !isNaN(hNum) && hNum >= 1 && hNum <= 12 ? String(hNum).padStart(2, '0') : '10';
    const mNum = parseInt(mVal, 10);
    const safeM = !isNaN(mNum) && mNum >= 0 && mNum <= 59 ? String(mNum).padStart(2, '0') : '00';
    return `${safeH}:${safeM} ${pVal}`;
  };

  const handleApply = () => {
    const finalTime = formatCleanTime(hour, minute, period);
    onSave(finalTime);
    onClose();
  };

  const updateHour = (hVal: string) => {
    setHour(hVal);
  };

  const updateMinute = (mVal: string) => {
    const clean = mVal.replace(':', '');
    setMinute(clean);
  };

  const updatePeriod = (pVal: 'AM' | 'PM') => {
    setPeriod(pVal);
  };

  const stepHour = (delta: number) => {
    const cur = parseInt(hour, 10) || 10;
    const next = ((cur - 1 + delta + 12) % 12) + 1;
    setHour(String(next).padStart(2, '0'));
  };

  const stepMinute = (delta: number) => {
    const cur = parseInt(minute, 10) || 0;
    const next = (cur + delta + 60) % 60;
    setMinute(String(next).padStart(2, '0'));
  };

  const hoursList = ['09', '10', '11', '12', '01', '02', '03', '04', '05', '06', '07', '08'];
  const minutesList = ['00', '15', '30', '45'];

  return (
    <>
      <div
        className="fixed inset-0 z-30"
        onClick={(e) => {
          e.stopPropagation();
          handleApply();
        }}
      />
      <div
        className="absolute right-0 top-full mt-1 z-40 w-64 bg-surface border border-border rounded-lg shadow-xl p-3 animate-in fade-in zoom-in-95 duration-150"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between pb-2 mb-2.5 border-b border-border">
          <div className="flex items-center gap-1.5 font-semibold text-xs text-text-primary">
            <Clock className="w-3.5 h-3.5 text-accent" />
            <span>Set Follow-up Time</span>
          </div>
          <button
            type="button"
            onClick={handleApply}
            className="text-text-muted hover:text-text-primary p-0.5 rounded hover:bg-surface-subtle cursor-pointer transition-colors"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>

        {/* Digital Time Display with Inputs & Steppers */}
        <div className="flex items-center justify-center gap-2 py-2 px-3 bg-surface-subtle border border-border rounded-md mb-2.5">
          {/* Hour input + steppers */}
          <div className="flex flex-col items-center">
            <button
              type="button"
              onClick={() => stepHour(1)}
              className="text-text-muted hover:text-text-primary p-0.5 hover:bg-surface rounded transition-colors cursor-pointer"
              title="Next hour"
            >
              <ChevronUp className="w-3 h-3" />
            </button>
            <input
              type="text"
              inputMode="numeric"
              maxLength={2}
              value={hour}
              onChange={(e) => {
                const v = e.target.value.replace(/[^0-9]/g, '');
                if (v.length <= 2) {
                  setHour(v);
                }
              }}
              onBlur={() => {
                const n = parseInt(hour, 10);
                const safeH = !isNaN(n) && n >= 1 && n <= 12 ? String(n).padStart(2, '0') : '10';
                setHour(safeH);
              }}
              className="w-10 text-center text-sm font-bold bg-surface border border-border rounded py-0.5 text-text-primary focus:outline-none focus:ring-1 focus:ring-accent font-mono"
              title="Type any hour (1-12)"
            />
            <button
              type="button"
              onClick={() => stepHour(-1)}
              className="text-text-muted hover:text-text-primary p-0.5 hover:bg-surface rounded transition-colors cursor-pointer"
              title="Previous hour"
            >
              <ChevronDown className="w-3 h-3" />
            </button>
          </div>

          <span className="text-base font-bold text-text-muted pb-1 select-none">:</span>

          {/* Minute input + steppers (Accepts ANY 00-59) */}
          <div className="flex flex-col items-center">
            <button
              type="button"
              onClick={() => stepMinute(5)}
              className="text-text-muted hover:text-text-primary p-0.5 hover:bg-surface rounded transition-colors cursor-pointer"
              title="+5 minutes"
            >
              <ChevronUp className="w-3 h-3" />
            </button>
            <input
              type="text"
              inputMode="numeric"
              maxLength={2}
              value={minute}
              onChange={(e) => {
                const v = e.target.value.replace(/[^0-9]/g, '');
                if (v.length <= 2) {
                  setMinute(v);
                }
              }}
              onBlur={() => {
                const n = parseInt(minute, 10);
                const safeM = !isNaN(n) && n >= 0 && n <= 59 ? String(n).padStart(2, '0') : '00';
                setMinute(safeM);
              }}
              className="w-10 text-center text-sm font-bold bg-surface border border-border rounded py-0.5 text-text-primary focus:outline-none focus:ring-1 focus:ring-accent font-mono"
              title="Type ANY minute (00-59)"
            />
            <button
              type="button"
              onClick={() => stepMinute(-5)}
              className="text-text-muted hover:text-text-primary p-0.5 hover:bg-surface rounded transition-colors cursor-pointer"
              title="-5 minutes"
            >
              <ChevronDown className="w-3 h-3" />
            </button>
          </div>

          {/* AM / PM Toggle */}
          <div className="flex flex-col gap-1 ml-1.5">
            <button
              type="button"
              onClick={() => updatePeriod('AM')}
              className={`px-2 py-0.5 text-[10px] font-bold rounded border transition-colors cursor-pointer ${
                period === 'AM'
                  ? 'bg-accent text-white border-accent shadow-xs'
                  : 'bg-surface border-border text-text-muted hover:text-text-primary'
              }`}
            >
              AM
            </button>
            <button
              type="button"
              onClick={() => updatePeriod('PM')}
              className={`px-2 py-0.5 text-[10px] font-bold rounded border transition-colors cursor-pointer ${
                period === 'PM'
                  ? 'bg-accent text-white border-accent shadow-xs'
                  : 'bg-surface border-border text-text-muted hover:text-text-primary'
              }`}
            >
              PM
            </button>
          </div>
        </div>

        {/* Quick Hour Tap Chips (1 to 12) */}
        <div className="mb-2">
          <div className="text-[10px] font-semibold text-text-muted mb-1 uppercase tracking-wider">
            Hour
          </div>
          <div className="grid grid-cols-6 gap-1">
            {hoursList.map((h) => {
              const isSel = (parseInt(hour, 10) || 10) === parseInt(h, 10);
              return (
                <button
                  key={h}
                  type="button"
                  onClick={() => updateHour(h)}
                  className={`py-0.5 text-[10px] font-semibold rounded border transition-colors cursor-pointer ${
                    isSel
                      ? 'bg-accent text-white border-accent shadow-xs'
                      : 'bg-surface hover:bg-surface-subtle border-border text-text-primary'
                  }`}
                >
                  {h}
                </button>
              );
            })}
          </div>
        </div>

        {/* Quick Minute Chips (or type ANY minute above) */}
        <div className="mb-2.5">
          <div className="text-[10px] font-semibold text-text-muted mb-1 uppercase tracking-wider">
            Quick Minutes
          </div>
          <div className="grid grid-cols-4 gap-1">
            {minutesList.map((m) => {
              const isSel = (parseInt(minute, 10) || 0) === parseInt(m, 10);
              return (
                <button
                  key={m}
                  type="button"
                  onClick={() => updateMinute(m)}
                  className={`py-0.5 text-[10px] font-mono font-medium rounded border transition-colors cursor-pointer ${
                    isSel
                      ? 'bg-accent text-white border-accent shadow-xs'
                      : 'bg-surface hover:bg-surface-subtle border-border text-text-primary'
                  }`}
                >
                  :{m}
                </button>
              );
            })}
          </div>
        </div>

        {/* Footer: Live preview + Apply / Done button */}
        <div className="pt-2 border-t border-border flex items-center justify-between">
          <div className="flex items-center gap-1">
            <span className="text-[10px] text-text-muted">Time:</span>
            <span className="text-[11px] font-mono text-accent font-bold">
              {formatCleanTime(hour, minute, period)}
            </span>
          </div>
          <button
            type="button"
            onClick={handleApply}
            className="px-3 py-1 bg-accent hover:bg-accent-hover text-white text-[10px] font-semibold rounded transition-colors cursor-pointer shadow-2xs"
          >
            Done
          </button>
        </div>
      </div>
    </>
  );
}

function FollowupTimeInput({
  value,
  onChange,
  placeholder = '10:00 AM',
  size = 'sm',
}: {
  value: string;
  onChange: (val: string) => void;
  placeholder?: string;
  size?: 'sm' | 'md';
}) {
  const parseTime = (str: string) => {
    const raw = (str || '').trim();
    const match = raw.match(/^(\d{1,2})(?::(\d{1,2}))?\s*(AM|PM)?$/i);
    let h = 10;
    let m = 0;
    let p: 'AM' | 'PM' = 'AM';
    if (match) {
      let parsedH = parseInt(match[1], 10);
      m = match[2] ? parseInt(match[2], 10) : 0;
      if (match[3]) {
        p = match[3].toUpperCase() === 'PM' ? 'PM' : 'AM';
      } else if (parsedH >= 12) {
        p = 'PM';
        if (parsedH > 12) parsedH -= 12;
      }
      if (parsedH === 0) parsedH = 12;
      h = Math.min(Math.max(1, parsedH), 12);
      m = Math.min(Math.max(0, m), 59);
    }
    return { hour: h, minute: m, period: p };
  };

  const parsed = parseTime(value);

  const handlePeriodToggle = (targetPeriod: 'AM' | 'PM') => {
    if (parsed.period === targetPeriod) return;
    const hStr = String(parsed.hour).padStart(2, '0');
    const mStr = String(parsed.minute).padStart(2, '0');
    onChange(`${hStr}:${mStr} ${targetPeriod}`);
  };

  const handleRawChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onChange(e.target.value);
  };

  const handleBlur = () => {
    if (value && value.trim()) {
      const p = parseTime(value);
      const hStr = String(p.hour).padStart(2, '0');
      const mStr = String(p.minute).padStart(2, '0');
      onChange(`${hStr}:${mStr} ${p.period}`);
    }
  };

  const isSmall = size === 'sm';

  return (
    <div className="space-y-1">
      <div className="flex items-center gap-1.5">
        <input
          type="text"
          value={value || ''}
          onChange={handleRawChange}
          onBlur={handleBlur}
          placeholder={placeholder}
          className={`flex-1 min-w-0 ${
            isSmall ? 'px-2 py-1 text-xs' : 'px-2.5 py-1.5 text-xs'
          } bg-surface border border-border rounded-sm text-text-primary focus:outline-none focus:border-accent font-mono`}
        />
        <div className="flex border border-border rounded-sm overflow-hidden text-[10px] font-semibold tracking-wider shrink-0 bg-surface">
          <button
            type="button"
            onClick={() => handlePeriodToggle('AM')}
            className={`px-2 py-1 transition-all cursor-pointer select-none ${
              parsed.period === 'AM'
                ? 'bg-accent text-white font-bold shadow-xs'
                : 'text-text-muted hover:text-text-primary hover:bg-surface-subtle'
            }`}
            title="Switch to Morning (AM)"
          >
            AM
          </button>
          <button
            type="button"
            onClick={() => handlePeriodToggle('PM')}
            className={`px-2 py-1 transition-all cursor-pointer select-none ${
              parsed.period === 'PM'
                ? 'bg-accent text-white font-bold shadow-xs'
                : 'text-text-muted hover:text-text-primary hover:bg-surface-subtle'
            }`}
            title="Switch to Evening (PM)"
          >
            PM
          </button>
        </div>
      </div>
      <div className="flex items-center gap-1 flex-wrap">
        {['10:00 AM', '11:30 AM', '02:00 PM', '04:30 PM', '06:00 PM'].map((preset) => {
          const isSelected = (value || '').trim().toUpperCase() === preset;
          return (
            <button
              key={preset}
              type="button"
              onClick={() => onChange(preset)}
              className={`px-1.5 py-0.5 rounded text-[9px] font-medium border transition-colors cursor-pointer ${
                isSelected
                  ? 'bg-accent/15 text-accent border-accent/40 font-semibold'
                  : 'bg-surface-subtle hover:bg-surface text-text-secondary border-border/80 hover:border-border-strong'
              }`}
            >
              {preset}
            </button>
          );
        })}
      </div>
    </div>
  );
}


export function getCustomerLeadStatus(cust?: {
  conversion_rate?: number | null;
  status?: string | null;
  converted?: boolean | null;
  lead_probability?: string | null;
  call_status?: string | null;
  [key: string]: any;
} | null) {
  if (!cust) {
    return {
      rate: 50,
      label: 'Warm Lead (50%)',
      shortLabel: 'Warm (50%)',
      type: 'warm' as const,
      icon: Sun,
      pillClass: 'bg-amber-50 hover:bg-amber-100 border-amber-200 text-amber-700 dark:bg-amber-950 dark:border-amber-800 dark:text-amber-300',
      iconColor: 'text-amber-600',
    };
  }
  const csLower = (cust.call_status || '').toLowerCase().trim();
  const statusLower = (cust.status || '').toLowerCase().trim();
  const completedCount = Number(cust.completed_bookings_count || 0);

  // Genuinely converted:
  // 1) Explicitly rate 100
  // 2) call_status contains 'convert' or 'won'
  // 3) Has completed/attended bookings (> 0)
  // 4) status is 'converted' AND conversion_rate is not 99 AND call_status is not 'confirm'/'book'
  const isRequest = csLower.includes('request');
  const is100 =
    cust.conversion_rate === 100 ||
    csLower.includes('convert') ||
    csLower.includes('won') ||
    completedCount > 0 ||
    (statusLower === 'converted' && cust.conversion_rate !== 99 && !csLower.includes('confirm') && !(csLower.includes('book') && !isRequest));

  // Booked / Scheduled (99%):
  // Must NOT be already converted.
  // Must have conversion_rate 99, or status 'booked', or call_status 'confirm'/'book'
  // Must NOT be 'booking requested' (which is an active inquiry/follow-up lead, not confirmed booked)
  const is99 = !is100 && !isRequest && (
    cust.conversion_rate === 99 ||
    statusLower === 'booked' ||
    csLower.includes('confirm') ||
    csLower.includes('book')
  );

  if (is100) {
    return {
      rate: 100,
      label: 'Converted (100%)',
      shortLabel: 'Converted (100%)',
      type: 'converted' as const,
      icon: CheckCircle2,
      pillClass: 'bg-emerald-50 hover:bg-emerald-100 border-emerald-300 text-emerald-800 dark:bg-emerald-950 dark:border-emerald-700 dark:text-emerald-200',
      iconColor: 'text-emerald-600',
    };
  }
  if (is99) {
    return {
      rate: 99,
      label: 'Booked (99%)',
      shortLabel: 'Booked (99%)',
      type: 'booked' as const,
      icon: CalendarCheck,
      pillClass: 'bg-teal-50 hover:bg-teal-100 border-teal-200 text-teal-700 dark:bg-teal-950 dark:border-teal-800 dark:text-teal-300',
      iconColor: 'text-teal-600',
    };
  }
  const rate = (cust.conversion_rate != null && (!isRequest || cust.conversion_rate < 99))
    ? cust.conversion_rate
    : (cust.lead_probability === 'hot' ? 90 : (cust.lead_probability === 'cold' ? 20 : 50));

  if (cust.lead_probability === 'hot' || rate >= 75) {
    const finalRate = rate >= 75 && rate < 99 ? rate : 90;
    return {
      rate: finalRate,
      label: `Hot Lead (${finalRate}%)`,
      shortLabel: `Hot (${finalRate}%)`,
      type: 'hot' as const,
      icon: Flame,
      pillClass: 'bg-rose-50 hover:bg-rose-100 border-rose-200 text-rose-700 dark:bg-rose-950 dark:border-rose-800 dark:text-rose-300',
      iconColor: 'text-rose-600',
    };
  }
  if (cust.lead_probability === 'cold' || rate < 40) {
    return {
      rate,
      label: `Cold Lead (${rate}%)`,
      shortLabel: `Cold (${rate}%)`,
      type: 'cold' as const,
      icon: Snowflake,
      pillClass: 'bg-sky-50 hover:bg-sky-100 border-sky-200 text-sky-700 dark:bg-sky-950 dark:border-sky-800 dark:text-sky-300',
      iconColor: 'text-sky-600',
    };
  }
  return {
    rate,
    label: `Warm Lead (${rate}%)`,
    shortLabel: `Warm (${rate}%)`,
    type: 'warm' as const,
    icon: Sun,
    pillClass: 'bg-amber-50 hover:bg-amber-100 border-amber-200 text-amber-700 dark:bg-amber-950 dark:border-amber-800 dark:text-amber-300',
    iconColor: 'text-amber-600',
  };
}

export function getLeadRateDisplay(cust?: any) {
  return getCustomerLeadStatus(cust);
}


