      const linkedCust = (customers || []).find((cu) => (cu.phone || '').replace(/[^0-9]/g, '').slice(-10) === normPhone);
      const prob = c.lead_probability || linkedCust?.lead_probability;
      const rate = c.conversion_rate ?? linkedCust?.conversion_rate ?? 0;
      const isRequest = (linkedCust?.call_status || '').toLowerCase().includes('request');
      const isConv = !isRequest && Boolean(c.converted || linkedCust?.converted || c.customer_status === 'converted' || linkedCust?.status === 'converted' || (c.conversion_rate != null && c.conversion_rate >= 99) || (linkedCust?.conversion_rate != null && linkedCust.conversion_rate >= 99));
