  function handleAddDropdownItem() {
    const trimmed = newDropdownItemInput.trim();
    if (!trimmed) return;
    const currentList = (editingDropdowns[dropdownActiveTab] || []) as any[];
    if (!currentList.some((item) => (typeof item === 'string' ? item : item?.label || item?.id || '').toLowerCase() === trimmed.toLowerCase())) {
      setEditingDropdowns((prev) => ({
        ...prev,
        [dropdownActiveTab]: [...((prev[dropdownActiveTab] as any[]) || []), trimmed],
        ...(dropdownActiveTab === 'next_actions' ? {
          next_action_colors: {
            ...(prev.next_action_colors || {}),
            [trimmed]: newDropdownItemColor,
          }
        } : {})
      }));
    }
    setNewDropdownItemInput('');
  }

  function handleRemoveDropdownItem(itemToRemove: string) {
    setEditingDropdowns((prev) => {
      const updatedColors = { ...(prev.next_action_colors || {}) };
      delete (updatedColors as any)[itemToRemove];
      return {
        ...prev,
        [dropdownActiveTab]: ((prev[dropdownActiveTab] as any[]) || []).filter((item: any) => (typeof item === 'string' ? item : item?.id) !== itemToRemove),
        ...(dropdownActiveTab === 'next_actions' ? { next_action_colors: updatedColors } : {}),
      };
    });
  }

  function handleStartEditItem(index: number, currentVal: string) {
    setEditingItemIndex(index);
    setEditingItemText(currentVal);
  }

  function handleSaveEditItem(index: number) {
    const trimmed = editingItemText.trim();
    if (!trimmed) return;
    setEditingDropdowns((prev) => {
      const list = [...((prev[dropdownActiveTab] as any[]) || [])];
      const oldVal = list[index];
      list[index] = trimmed;
      const updatedColors = { ...(prev.next_action_colors || {}) };
      const oldKey = typeof oldVal === 'string' ? oldVal : (oldVal as any)?.id;
      if (oldKey && (updatedColors as any)[oldKey]) {
        (updatedColors as any)[trimmed] = (updatedColors as any)[oldKey];
        if (oldKey !== trimmed) delete (updatedColors as any)[oldKey];
      }
      return {
        ...prev,
        [dropdownActiveTab]: list,
        ...(dropdownActiveTab === 'next_actions' ? { next_action_colors: updatedColors } : {}),
      };
    });
    setEditingItemIndex(null);
    setEditingItemText('');
  }

