  async function handleUpdateBookingStatus(
    bookingId: string,
    newStatus: string,
    newStartTime?: string,
    sendReview?: boolean,
    checkoutData?: {
      fee_amount?: number;
      payment_status?: string;
      payment_mode?: string;
      generate_invoice?: boolean;
      send_invoice_whatsapp?: boolean;
      billing_breakdown?: Record<string, number>;
    }
  ) {
    setUpdatingBookingId(bookingId);
    setActionNotice(null);
    try {
      await crm.updateBookingStatus(bookingId, newStatus, newStartTime, undefined, sendReview, checkoutData);
      setBookings((prev) =>
        prev.map((b) => (b.id === bookingId ? {
          ...b,
          status: newStatus,
          ...(newStartTime ? { start_time: newStartTime } : {}),
          ...(checkoutData?.fee_amount !== undefined ? { price: checkoutData.fee_amount } : {}),
          ...(checkoutData?.payment_status ? { payment_status: checkoutData.payment_status } : {}),
          ...(checkoutData?.payment_mode ? { payment_mode: checkoutData.payment_mode } : {}),
        } : b))
      );
      if (selectedBookingDetail && selectedBookingDetail.id === bookingId) {
        setSelectedBookingDetail({
          ...selectedBookingDetail,
          status: newStatus,
          ...(newStartTime ? { start_time: newStartTime } : {}),
          ...(checkoutData?.fee_amount !== undefined ? { price: checkoutData.fee_amount } : {}),
          ...(checkoutData?.payment_status ? { payment_status: checkoutData.payment_status } : {}),
          ...(checkoutData?.payment_mode ? { payment_mode: checkoutData.payment_mode } : {}),
        });
      }

      if (newStatus === 'attended') {
        const targetB = bookings.find((b) => b.id === bookingId);
        if (targetB) {
          const cleanBPhone = (targetB.contact_phone || '').replace(/[^0-9]/g, '').slice(-10);
          setCustomers((prev) =>
            prev.map((c) => {
              const cleanCPhone = (c.phone || '').replace(/[^0-9]/g, '').slice(-10);
              if (
                (cleanBPhone && cleanCPhone && cleanCPhone === cleanBPhone) ||
                (targetB.contact_name && c.name && c.name.toLowerCase() === targetB.contact_name.toLowerCase())
              ) {
                return {
                  ...c,
                  converted: true,
                  conversion_rate: 100,
                  status: 'converted',
                  lead_probability: 'converted',
                };
              }
              return c;
            })
          );
        }
        loadCustomers();
        if (sendReview === false) {
          setActionNotice('Client marked Attended & Converted (100%)! Review template was skipped.');
        } else {
          setActionNotice('Client marked Attended & Converted (100%)! Post-service review request scheduled.');
        }
      } else if (newStatus === 'completed') {
        const targetB = bookings.find((b) => b.id === bookingId);
        if (targetB) {
          const cleanBPhone = (targetB.contact_phone || '').replace(/[^0-9]/g, '').slice(-10);
          setCustomers((prev) =>
            prev.map((c) => {
              const cleanCPhone = (c.phone || '').replace(/[^0-9]/g, '').slice(-10);
              if (
                (cleanBPhone && cleanCPhone && cleanCPhone === cleanBPhone) ||
                (targetB.contact_name && c.name && c.name.toLowerCase() === targetB.contact_name.toLowerCase())
              ) {
                if (c.conversion_rate === 100) return c;
                return {
                  ...c,
                  converted: true,
                  conversion_rate: 99,
                  status: 'booked',
                  lead_probability: 'booked',
                };
              }
              return c;
            })
          );
        }
        loadCustomers();
        setActionNotice('Appointment marked Completed (Booked 99%). Mark as Attended to convert 100%.');
      } else if (newStatus === 'no_show') {
        if (sendReview === false) {
          setActionNotice('Client marked Not Came. Reschedule WhatsApp nudge was skipped.');
        } else {
          setActionNotice('Client marked Not Came! Reschedule nudge WhatsApp template sent to client.');
        }
      } else if (newStatus === 'cancelled') {
        if (sendReview === false) {
          setActionNotice('Booking Cancelled. Cancellation WhatsApp notice was skipped.');
        } else {
          setActionNotice('Booking Cancelled. Cancellation notification WhatsApp template sent to client.');
        }
      } else if (newStatus === 'confirmed') {
        setActionNotice('Booking Confirmed! Official confirmation WhatsApp template sent to client.');
      } else if (newStatus === 'rescheduled') {
        setActionNotice('Booking Rescheduled! Reschedule confirmation WhatsApp template sent to client.');
      }
      setTimeout(() => setActionNotice(null), 5500);
      loadBookings();
    } catch (err) {
      alert('Failed to update booking status.');
    } finally {
      setUpdatingBookingId(null);
    }
  }

  async function handleDeleteBooking(bookingId: string) {
    if (!window.confirm('Are you sure you want to permanently delete this booking? This action cannot be undone.')) {
      return;
    }
    setDeletingBookingId(bookingId);
    setActionNotice(null);
    try {
      await crm.deleteBooking(bookingId);
      setBookings((prev) => prev.filter((b) => b.id !== bookingId));
      if (selectedBookingDetail && selectedBookingDetail.id === bookingId) {
        setIsBookingDetailModalOpen(false);
        setSelectedBookingDetail(null);
      }
      setActionNotice('Booking permanently deleted.');
      setTimeout(() => setActionNotice(null), 4000);
      loadBookings();
    } catch (err: any) {
      alert(err instanceof Error ? err.message : 'Failed to delete booking. Only cancelled or not came bookings can be deleted.');
    } finally {
      setDeletingBookingId(null);
    }
  }

  async function handleRescheduleBooking(bookingId: string, newDate: string, newTime: string) {
    if (!newDate || !newTime) {
      alert('Please select both a new date and time to reschedule.');
      return;
    }
    setIsRescheduling(true);
    try {
      const newStartTime = `${newDate}T${newTime}:00`;
      await handleUpdateBookingStatus(bookingId, 'rescheduled', newStartTime);
      setIsBookingDetailModalOpen(false);
      setSelectedBookingDetail(null);
      loadCalendarData();
    } catch (err: any) {
      alert(err instanceof Error ? err.message : 'Failed to reschedule booking.');
    } finally {
      setIsRescheduling(false);
    }
  }

  async function handleBookAnotherAppointment(b: Booking | null, date: string, time: string, service?: string) {
    if (!b) return;
    if (!date || !time) {
      alert('Please select both a date and time for the new appointment.');
      return;
    }
    setIsBookingAnother(true);
    try {
      const startTime = `${date}T${time}:00`;
      const staffVal = b.staff_member || (b as any).doctor_name || (b as any).doctor || undefined;
      const serviceVal = (service || b.service || currentTaxonomy.requirement_label || 'Consultation').trim();
      await crm.createBooking({
        contact_name: (b.contact_name || 'Client').trim(),
        contact_phone: (b.contact_phone || '').trim(),
        service: serviceVal,
        staff_member: staffVal,
        doctor_name: staffVal,
        start_time: startTime,
        price: Number(b.price) || 0,
        notes: `Follow-up appointment booked for ${b.contact_name || 'Client'}`,
        send_whatsapp_confirmation: true,
        payment_mode: (b as any).payment_mode || 'pay_at_clinic',
        payment_status: 'unpaid',
      });
      setActionNotice(`New appointment booked for ${b.contact_name || 'Client'} on ${date} at ${formatMilitaryTo12(time)}!`);
      setTimeout(() => setActionNotice(null), 3500);
      setIsBookingDetailModalOpen(false);
      setSelectedBookingDetail(null);
      loadBookings();
      loadCalendarData();
    } catch (err: any) {
      console.error('Failed to book another appointment:', err);
      alert(err instanceof Error ? err.message : 'Failed to book another appointment.');
    } finally {
      setIsBookingAnother(false);
    }
  }

  async function handleUpdatePrice(bookingId: string, newPrice: number, breakdown?: Record<string, number>) {
    if (isNaN(newPrice) || newPrice < 0) {
      setActionNotice('Please enter a valid non-negative price.');
      setTimeout(() => setActionNotice(null), 3000);
      return;
    }
    setUpdatingPrice(true);
    try {
      await crm.updateBookingPrice(bookingId, newPrice, breakdown);
      setBookings((prev) =>
        prev.map((b) => {
          if (b.id !== bookingId) return b;
          let safeMeta = b.metadata;
          if (typeof safeMeta === 'string') {
            try { safeMeta = JSON.parse(safeMeta); } catch { safeMeta = {}; }
          }
          if (!safeMeta || typeof safeMeta !== 'object' || Array.isArray(safeMeta)) safeMeta = {};
          return {
            ...b,
            price: newPrice,
            metadata: breakdown ? { ...safeMeta, billing_breakdown: breakdown } : safeMeta,
          };
        })
      );
      if (selectedBookingDetail && selectedBookingDetail.id === bookingId) {
        let selMeta = selectedBookingDetail.metadata;
        if (typeof selMeta === 'string') {
          try { selMeta = JSON.parse(selMeta); } catch { selMeta = {}; }
        }
        if (!selMeta || typeof selMeta !== 'object' || Array.isArray(selMeta)) selMeta = {};
        setSelectedBookingDetail({
          ...selectedBookingDetail,
          price: newPrice,
          metadata: breakdown ? { ...selMeta, billing_breakdown: breakdown } : selMeta,
        });
      }
      setEditingBookingPriceId(null);
      setActionNotice(`Booking fee updated to ${currentCurrencySymbol}${newPrice}`);
      setTimeout(() => setActionNotice(null), 3500);
    } catch (err) {
      console.error('Failed to update booking price:', err);
      setActionNotice('Failed to update price. Please try again.');
      setTimeout(() => setActionNotice(null), 3500);
    } finally {
      setUpdatingPrice(false);
    }
  }


  function navigateTo(tab: 'overview' | 'inbox' | 'bookings' | 'calendar' | 'customers' | 'repeat_clients' | 'followup' | 'marketing' | 'settings' | 'team' | 'billing' | 'reviews') {
    if (tab === 'reviews' && !isSmaato) {
      setActiveNav('overview');
      return;
    }
    if (tab === 'repeat_clients') {
      setActiveNav('customers');
      setFollowupView('repeat');
      if (typeof window !== 'undefined') {
        try {
          localStorage.setItem('whatsapp_crm_active_nav', 'customers');
          localStorage.setItem('whatsapp_crm_followup_view', 'repeat');
          window.history.replaceState(null, '', `${window.location.pathname}#customers`);
        } catch {}
      }
      return;
    }
    if (tab === 'calendar') {
      setActiveNav('bookings');
      setBookingViewTab('calendar');
      if (typeof window !== 'undefined') {
        try {
          localStorage.setItem('whatsapp_crm_active_nav', 'bookings');
          localStorage.setItem('whatsapp_crm_booking_view_tab', 'calendar');
          window.history.replaceState(null, '', `${window.location.pathname}#bookings`);
        } catch {}
      }
      return;
    }
    if (tab === 'bookings') {
      setActiveNav('bookings');
      setBookingViewTab('table');
      if (typeof window !== 'undefined') {
        try {
          localStorage.setItem('whatsapp_crm_active_nav', 'bookings');
          localStorage.setItem('whatsapp_crm_booking_view_tab', 'table');
          window.history.replaceState(null, '', `${window.location.pathname}#bookings`);
        } catch {}
      }
      setIsBookingDetailModalOpen(false);
      setSelectedBookingDetail(null);
      setIsAddBookingOpen(false);
      return;
    }
    setActiveNav(tab);
    if (typeof window !== 'undefined') {
      try {
        localStorage.setItem('whatsapp_crm_active_nav', tab);
        window.history.replaceState(null, '', `${window.location.pathname}#${tab}`);
      } catch {}
    }
    setIsBookingDetailModalOpen(false);
    setSelectedBookingDetail(null);
    setIsAddBookingOpen(false);
    if (tab === 'inbox') {
      if (typeof window !== 'undefined' && window.innerWidth >= 768) {
        if (!selectedConvRef.current && conversations.length > 0 && !hasAutoSelectedInitialChatRef.current) {
          hasAutoSelectedInitialChatRef.current = true;
          selectConversation(conversations[0]);
        }
      } else {
        setSelectedConv(null);
      }
    }
  }

