  async function handleUploadTemplatePoster(file: File) {
    if (!file) return;
    if (file.size > 25 * 1024 * 1024) {
      setTemplateManagerError('Poster image must be less than 25MB.');
      return;
    }
    // 1. Instant local preview so the user immediately sees the poster on screen
    const localBlobUrl = URL.createObjectURL(file);
    setNewTemplateForm(prev => ({ ...prev, header_sample_url: localBlobUrl }));
    setUploadingPosterImage(true);
    setTemplateManagerError(null);

    try {
      const res = await marketing.uploadMedia(file);
      if (res && res.url) {
        // 2. Seamlessly update to the permanent cloud HTTPS URL
        setNewTemplateForm(prev => ({ ...prev, header_sample_url: res.url }));
      } else {
        throw new Error('Upload succeeded but no public URL was returned.');
      }
    } catch (err: any) {
      console.error('Failed to upload poster image:', err);
      setTemplateManagerError(err.message || 'Failed to upload poster image to server.');
    } finally {
      setUploadingPosterImage(false);
    }
  }

  async function handleUploadCampaignPoster(file: File) {
    if (!file) return;
    if (file.size > 25 * 1024 * 1024) {
      setActionNotice('Poster image must be less than 25MB.');
      setTimeout(() => setActionNotice(null), 3500);
      return;
    }
    // 1. Instant local preview
    const localBlobUrl = URL.createObjectURL(file);
    setCampaignForm(prev => ({ ...prev, header_image_url: localBlobUrl }));
    setUploadingCampaignPoster(true);

    try {
      const res = await marketing.uploadMedia(file);
      if (res && res.url) {
        setCampaignForm(prev => ({ ...prev, header_image_url: res.url }));
        setActionNotice('Poster image uploaded successfully!');
        setTimeout(() => setActionNotice(null), 3000);
      } else {
        throw new Error('Upload succeeded but no public URL was returned.');
      }
    } catch (err: any) {
      console.error('Failed to upload campaign poster:', err);
      setActionNotice(err.message || 'Failed to upload campaign poster to server.');
      setTimeout(() => setActionNotice(null), 4000);
    } finally {
      setUploadingCampaignPoster(false);
    }
  }

